import AVFoundation
import CoreVideo
import Foundation

// Playback.swift's transport on a real AVPlayer, with the item built the way
// the preview's is: a custom compositor, seekingWaitsForVideoCompositionRendering,
// times at 600,000 a second, one seek in flight, the guard of timeAdvanced.
// args: file, loop start s, loop end s (or "end"), rate, seconds to watch
final class PassThrough: NSObject, AVVideoCompositing {
    var sourcePixelBufferAttributes: [String: any Sendable]? {
        [kCVPixelBufferPixelFormatTypeKey as String: REDACTED]
    }
    var requiredPixelBufferAttributesForRenderContext: [String: any Sendable] {
        [kCVPixelBufferPixelFormatTypeKey as String: REDACTED]
    }
    func renderContextChanged(_ c: AVVideoCompositionRenderContext) {}
    func startRequest(_ r: AVAsynchronousVideoCompositionRequest) {
        if let id = r.sourceTrackIDs.first?.int32Value, let b = r.sourceFrame(byTrackID: id) {
            r.finish(withComposedVideoFrame: b)
        } else if let b = r.renderContext.newPixelBuffer() {
            r.finish(withComposedVideoFrame: b)
        } else {
            r.finishCancelledRequest()
        }
    }
}

let perSecond: Int64 = 600_000
func time(_ t: Int64) -> CMTime { CMTime(value: t, timescale: CMTimeScale(perSecond)) }
func ticks(_ t: CMTime) -> Int64 {
    guard t.isNumeric else { return 0 }
    return CMTimeConvertScale(t, timescale: CMTimeScale(perSecond), method: .roundHalfAwayFromZero).value
}

let a = CommandLine.arguments
let asset = AVURLAsset(url: URL(fileURLWithPath: a[1]))
let composition = AVMutableComposition()
let videoSource = asset.tracks(withMediaType: .video)[0]
let audioSource = asset.tracks(withMediaType: .audio).first
let plan = ticks(videoSource.timeRange.duration) / 20_000 * 20_000  // whole frames at 30 fps
let v = composition.addMutableTrack(withMediaType: .video, preferredTrackID: 1)!
try v.insertTimeRange(CMTimeRange(start: .zero, duration: time(plan)), of: videoSource, at: .zero)
if let audioSource {
    let s = composition.addMutableTrack(withMediaType: .audio, preferredTrackID: 2)!
    try s.insertTimeRange(CMTimeRange(start: .zero, duration: time(plan)), of: audioSource, at: .zero)
}
let loopStart = Int64((Double(a[2])! * Double(perSecond)).rounded())
let loopEnd = a[3] == "end" ? plan : Int64((Double(a[3])! * Double(perSecond)).rounded())
let rate = Float(a[4])!
let watch = Double(a[5])!

let videoComposition = AVMutableVideoComposition()
videoComposition.customVideoCompositorClass = PassThrough.self
videoComposition.frameDuration = CMTime(value: 1, timescale: 30)
videoComposition.renderSize = videoSource.naturalSize
let instruction = AVMutableVideoCompositionInstruction()
instruction.timeRange = CMTimeRange(start: .zero, duration: composition.duration)
let layer = AVMutableVideoCompositionLayerInstruction(assetTrack: v)
instruction.layerInstructions = [layer]
videoComposition.instructions = [instruction]

let item = AVPlayerItem(asset: composition)
item.videoComposition = videoComposition
item.seekingWaitsForVideoCompositionRendering = true
let player = AVPlayer(playerItem: item)
player.isMuted = true
player.actionAtItemEnd = .pause
player.automaticallyWaitsToMinimizeStalling = false
let playerLayer = AVPlayerLayer(player: player)  // the preview has one; it drives the compositor
_ = playerLayer

var isSeeking = false
var serial = 0
var seeks = 0
var stops: [Double] = []
func seek(to t: Int64) {
    guard !isSeeking else { return }
    isSeeking = true
    serial += 1
    let mine = serial
    player.seek(to: time(t), toleranceBefore: .zero, toleranceAfter: .zero) { _ in
        DispatchQueue.main.async {
            guard mine == serial else { return }
            isSeeking = false
        }
    }
}
let observer = player.addPeriodicTimeObserver(
    forInterval: CMTime(value: 1, timescale: 60), queue: .main
) { t in
    let now = max(0, ticks(t))
    guard player.rate != 0, loopEnd > loopStart, now >= loopEnd else { return }
    seeks += 1
    seek(to: loopStart)
}
let rateWatch = player.observe(\.rate, options: [.new]) { p, _ in
    if p.rate == 0 { stops.append(p.currentTime().seconds) }
}

// Wait for the item, then start the way play() and setRate() do.
let ready = Date().addingTimeInterval(5)
while item.status != .readyToPlay, Date() < ready {
    RunLoop.main.run(until: Date().addingTimeInterval(0.02))
}
player.seek(to: time(loopStart), toleranceBefore: .zero, toleranceAfter: .zero)
RunLoop.main.run(until: Date().addingTimeInterval(0.3))
player.rate = rate
RunLoop.main.run(until: Date().addingTimeInterval(watch))
let line = String(
    format: "plan %.3f comp %.6f loop %.3f..%.3f rate %.0f: seeks %d, stops %@, after %.1f s time %.3f rate %.0f",
    Double(plan) / Double(perSecond), composition.duration.seconds, Double(loopStart) / Double(perSecond),
    Double(loopEnd) / Double(perSecond), rate, seeks, "\(stops)", watch, player.currentTime().seconds, player.rate)
print(line)
_ = observer
_ = rateWatch
exit(0)

